-- Survey commands are fenced before provider execution; an unknown send is never replayed.
CREATE TABLE csat_settings(project_id TEXT PRIMARY KEY REFERENCES projects(id),enabled INTEGER NOT NULL DEFAULT 0,scale TEXT NOT NULL CHECK(scale IN ('thumbs','five')),delay_minutes INTEGER NOT NULL,expires_days INTEGER NOT NULL,locale TEXT NOT NULL,enabled_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE csat_surveys(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),resolution_id TEXT NOT NULL UNIQUE REFERENCES conversation_resolutions(id),conversation_id TEXT NOT NULL,contact_id TEXT NOT NULL,recipient TEXT NOT NULL,channel TEXT NOT NULL DEFAULT 'email',scale TEXT NOT NULL CHECK(scale IN ('thumbs','five')),locale TEXT NOT NULL,due_at INTEGER NOT NULL,expires_at INTEGER NOT NULL,state TEXT NOT NULL CHECK(state IN ('pending','sending','sent','suppressed','failed','uncertain','cancelled')),token_revision INTEGER NOT NULL DEFAULT 0,revoked_at INTEGER,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE INDEX csat_surveys_due ON csat_surveys(state,due_at);
CREATE INDEX csat_surveys_contact ON csat_surveys(project_id,contact_id);
CREATE TABLE csat_responses(resolution_id TEXT PRIMARY KEY REFERENCES conversation_resolutions(id),project_id TEXT NOT NULL,contact_id TEXT NOT NULL,channel TEXT NOT NULL CHECK(channel IN ('email','widget')),scale TEXT NOT NULL CHECK(scale IN ('thumbs','five')),score INTEGER NOT NULL CHECK(score BETWEEN -1 AND 5 AND score!=0),reason TEXT NOT NULL,comment TEXT NOT NULL CHECK(length(comment)<=1000),revision INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE INDEX csat_responses_project ON csat_responses(project_id,updated_at,resolution_id);
CREATE TABLE csat_response_history(id TEXT PRIMARY KEY,resolution_id TEXT NOT NULL REFERENCES conversation_resolutions(id),project_id TEXT NOT NULL,contact_id TEXT NOT NULL,channel TEXT NOT NULL,scale TEXT NOT NULL,score INTEGER NOT NULL,reason TEXT NOT NULL,comment TEXT NOT NULL CHECK(length(comment)<=1000),revision INTEGER NOT NULL,created_at INTEGER NOT NULL,UNIQUE(resolution_id,revision));
CREATE TABLE csat_optouts(project_id TEXT NOT NULL REFERENCES projects(id),contact_id TEXT NOT NULL,created_at INTEGER NOT NULL,PRIMARY KEY(project_id,contact_id));
-- Preserve the existing widget ratings as the first canonical cycle response.
INSERT INTO csat_responses SELECT v.resolution_id,r.project_id,r.contact_id,'widget','thumbs',v.value,'',v.comment,v.revision,v.updated_at FROM conversation_ratings v JOIN conversation_resolutions r ON r.id=v.resolution_id;
INSERT INTO csat_response_history SELECT v.id,v.resolution_id,r.project_id,r.contact_id,'widget','thumbs',v.value,'',v.comment,v.revision,v.created_at FROM conversation_rating_history v JOIN conversation_resolutions r ON r.id=v.resolution_id;
